Nítido. El orden en la resta importa: inicial menos actual da el peso perdido como número positivo, que es lo que queremos. Ahora armemos el programa completo:

```c
#include <stdio.h>

int main() {
    int n, contador;
    float peso_inicial, peso_actual, perdida, suma, promedio;

    printf("Cuantos clientes tiene el gimnasio? ");
    scanf("%d", &n);

    suma = 0;
    contador = 0;

    while (contador < n) {
        printf("Cliente %d - Peso inicial (kg): ", contador + 1);
        scanf("%f", &peso_inicial);
        printf("Cliente %d - Peso actual (kg):  ", contador + 1);
        scanf("%f", &peso_actual);

        perdida = peso_inicial - peso_actual;  // inicial - actual = positivo si bajo de peso
        suma = suma + perdida;
        contador = contador + 1;
    }

    promedio = suma / n;
    printf("Perdida promedio: %.2f kg\n", promedio);

    return 0;
}
```

